create sequence public.seq_packing_record start 1;
create table public.packing_records(packing_record_id uuid primary key default gen_random_uuid(),production_batch_id uuid not null references public.production_batches(production_batch_id),packing_record_no text not null unique,packed_date date not null default current_date,quantity numeric not null check(quantity>0),uom_id uuid not null references public.uoms(uom_id),roll_count int,carton_count int,roll_length numeric,location_id uuid not null references public.locations(location_id),packed_by text,remarks text,created_at timestamptz not null default now(),created_by text not null default 'system',updated_at timestamptz not null default now(),updated_by text);
create table public.finished_goods(finished_goods_id uuid primary key default gen_random_uuid(),product_id uuid not null references public.products(product_id),production_batch_id uuid not null references public.production_batches(production_batch_id),packing_record_id uuid not null references public.packing_records(packing_record_id),quantity numeric not null check(quantity>0),uom_id uuid not null references public.uoms(uom_id),location_id uuid not null references public.locations(location_id),ownership text not null default'INTERCONVERTERS_OWNED',status text not null default'AVAILABLE' check(status in('AVAILABLE','ALLOCATED','DISPATCHED','HOLD')),created_at timestamptz not null default now(),created_by text not null default 'system',updated_at timestamptz not null default now(),updated_by text);
alter table public.stock_ledger drop constraint stock_ledger_source_type;alter table public.stock_ledger add constraint stock_ledger_source_type check(source_transaction_type in('GRN','PRODUCTION_ENTRY','PACKING_RECORD','ADJUSTMENT','OPENING_BALANCE'));
alter table public.production_orders drop constraint production_orders_status_check;alter table public.production_orders add constraint production_orders_status_check check(status in('ORDER_CONFIRMED','PRODUCTION_PLANNED','MATERIALS_PENDING','MATERIALS_READY','MACHINE_ASSIGNED','IN_SETUP','IN_PRODUCTION','ON_HOLD','QC_PENDING','QC_HOLD','QC_APPROVED','PACKING','FINISHED','CANCELLED'));
create or replace function public.pack_finished_goods(p_batch uuid,p_quantity numeric,p_rolls int,p_cartons int,p_roll_length numeric,p_packed_by text,p_remarks text)returns uuid language plpgsql security definer set search_path=public as $$ declare v_pack uuid;v_fg uuid;v_order uuid;v_product uuid;v_mtr uuid;v_wip uuid;v_store uuid;v_no text;begin if not has_factory_role(auth.uid(),array['admin','store'])then raise exception'not authorized';end if;if p_quantity<=0 then raise exception'quantity must be greater than zero';end if;select b.production_order_id,po.product_id into v_order,v_product from production_batches b join production_orders po using(production_order_id)where b.production_batch_id=p_batch and po.status='QC_APPROVED' for update of po;if not found then raise exception'batch is not QC approved';end if;select uom_id into v_mtr from uoms where uom_code='MTR';select location_id into v_wip from locations where location_code='WIP-FLOOR';select location_id into v_store from locations where location_code='FG-STORE';v_no:='PK-'||to_char(current_date,'YYYYMMDD')||'-'||lpad(nextval('seq_packing_record')::text,4,'0');insert into packing_records(production_batch_id,packing_record_no,quantity,uom_id,roll_count,carton_count,roll_length,location_id,packed_by,remarks,created_by)values(p_batch,v_no,p_quantity,v_mtr,p_rolls,p_cartons,p_roll_length,v_store,p_packed_by,p_remarks,auth.uid()::text)returning packing_record_id into v_pack;insert into finished_goods(product_id,production_batch_id,packing_record_id,quantity,uom_id,location_id,created_by)values(v_product,p_batch,v_pack,p_quantity,v_mtr,v_store,auth.uid()::text)returning finished_goods_id into v_fg;insert into stock_ledger(product_id,quantity,uom_id,location_id,ownership,stock_category,source_transaction_type,source_transaction_id,batch_id,reference_note,created_by)values(v_product,-p_quantity,v_mtr,v_wip,'INTERCONVERTERS_OWNED','WIP','PACKING_RECORD',v_pack,p_batch,v_no||' WIP issue',auth.uid()::text),(v_product,p_quantity,v_mtr,v_store,'INTERCONVERTERS_OWNED','FINISHED_GOODS','PACKING_RECORD',v_pack,p_batch,v_no||' finished goods receipt',auth.uid()::text);update production_orders set status='FINISHED',updated_at=now(),updated_by=auth.uid()::text where production_order_id=v_order;insert into audit_log(user_id,action,entity_type,entity_id,new_value)values(auth.uid(),'Packing Completed','packing_records',v_pack,jsonb_build_object('record_no',v_no,'quantity',p_quantity,'finished_goods_id',v_fg));return v_pack;end $$;
alter table public.packing_records enable row level security;alter table public.finished_goods enable row level security;create policy factory_read_packing on public.packing_records for select using(has_factory_role(auth.uid(),array['admin','production_manager','supervisor','operator','store','quality','accounts','viewer']));create policy factory_read_finished on public.finished_goods for select using(has_factory_role(auth.uid()));grant execute on function public.pack_finished_goods(uuid,numeric,int,int,numeric,text,text)to authenticated;
